/* Odyssey: The Long Way Home. Rapid-recall question bank, Unit 1 Learning and Cognition.
   Fields: id, t (topic), lv (1 recall, 2 understand/classify, 3 apply/evaluate), q, a, d (3 distractors),
   tf:1 for true/false items (a is true/false, no d), why (shown after answering). */
window.ODY = window.ODY || {};
window.ODY.questions = [

/* ---------- The six IB concepts ---------- */
{id:"co01", t:"concepts", lv:1, q:"Which concept asks whether we can conclude that one variable produced a change in another?", a:"Causality", d:["Measurement","Perspective","Change"], why:"Causality is about whether a cause-and-effect claim is justified, for example by manipulating an IV under controlled conditions."},
{id:"co02", t:"concepts", lv:1, q:"Which concept covers ethics and how research findings should, and should not, be used?", a:"Responsibility", d:["Perspective","Bias","Change"], why:"Responsibility covers research ethics and the careful, fair use of findings in society."},
{id:"co03", t:"concepts", lv:1, q:"Which concept is about how psychologists operationalise constructs and how valid their tools are?", a:"Measurement", d:["Causality","Bias","Perspective"], why:"Measurement asks how an invisible construct is turned into something countable, and whether that count is valid."},
{id:"co04", t:"concepts", lv:1, q:"In IB Psychology, bias is best defined as...", a:"A systematic error in thinking or research", d:["Any study that uses a small or narrow sample","A deliberate choice of theoretical lens","A random error that cancels out over trials"], why:"Bias is systematic and usually unintended. A deliberate lens is a perspective, not a bias."},
{id:"co05", t:"concepts", lv:1, q:"Which concept includes free will versus determinism, locus of control and self-efficacy?", a:"Change", d:["Perspective","Responsibility","Causality"], why:"Change covers how thinking and behaviour can change, including agency and how much we are determined."},
{id:"co06", t:"concepts", lv:2, tf:1, q:"Studying memory only from a biological approach makes a study biased.", a:false, why:"Choosing one approach is a perspective, a deliberate lens. Bias is an unintended, systematic distortion."},
{id:"co07", t:"concepts", lv:1, q:"If a perspective is the pair of glasses you look through, then bias is...", a:"A smudge on the glasses", d:["The frame of the glasses","A second pair of glasses","The person wearing them"], why:"A perspective is a chosen lens that adds depth. Bias is a flaw on that lens that distorts what you see."},
{id:"co08", t:"concepts", lv:2, q:"Which sentence is the safer way to write about a study in a Section C essay?", a:"A control group strengthens internal validity", d:["The study had high internal validity","Causality in this study was low","The study was biased, unethical and lacked validity"], why:"Avoid vague absolutes. Say what strengthens or limits validity or a causal claim, and why."},
{id:"co09", t:"concepts", lv:2, q:"Some of Bandura's observers knew the children they were rating. Which concept does this criticism belong to?", a:"Bias", d:["Responsibility","Change","Perspective"], why:"Observers who know participants may code their behaviour unevenly: a form of researcher (observer) bias."},
{id:"co10", t:"concepts", lv:2, q:"Pavlov recorded saliva, an objective response, but ignored the dog's inner states. Which concept is this point about?", a:"Measurement", d:["Causality","Responsibility","Change"], why:"Salivation is easy to quantify, but it leaves out mental states: a measurement point."},
{id:"co11", t:"concepts", lv:2, q:"Could patient HM give informed consent to decades of testing? This question belongs to which concept?", a:"Responsibility", d:["Measurement","Bias","Causality"], why:"Consent, confidentiality and protecting a vulnerable participant are responsibility issues."},
{id:"co12", t:"concepts", lv:2, q:"Bartlett's stories became shorter and more conventional with each recall. Which concept fits memory altering over time?", a:"Change", d:["Causality","Measurement","Responsibility"], why:"Memory being reshaped across reproductions is a clear example of change over time."},
{id:"co13", t:"concepts", lv:2, q:"Bransford and Johnson randomly allocated participants to conditions. This point mainly supports a claim about...", a:"Causality", d:["Perspective","Responsibility","Change"], why:"Random allocation spreads participant differences across groups, so the IV is the likelier cause."},
{id:"co14", t:"concepts", lv:2, q:"Using HM for a biological lens and serial position data for a cognitive lens on the MSM is a point about...", a:"Perspective", d:["Bias","Measurement","Change"], why:"Weighing two lenses on the same model, and what each explains, is the heart of a perspective essay."},
{id:"co15", t:"concepts", lv:2, tf:1, q:"A sampling problem, such as testing only university students, mainly limits ecological validity.", a:false, why:"Sampling limits population (external) validity. Ecological validity is about how realistic the task or setting is."},
{id:"co16", t:"concepts", lv:2, q:"Mani et al. inferred cognitive load from income and harvest season, never measuring it directly. Which concept?", a:"Measurement", d:["Responsibility","Change","Perspective"], why:"Load was an assumed construct, not a directly measured variable: a measurement limitation."},
{id:"co17", t:"concepts", lv:2, q:"'Change your thinking and you can change your behaviour' (soft determinism) is linked most closely to...", a:"Change", d:["Measurement","Bias","Causality"], why:"Soft determinism leaves room for agency and change, the middle ground the cognitive approach takes."},
{id:"co18", t:"concepts", lv:2, tf:1, q:"A correlation can never tell us anything useful about causes.", a:false, why:"Correlation is a hint. Criteria like temporality, dose-response and consistency can strengthen a causal case."},
{id:"co19", t:"concepts", lv:2, q:"Stress raises cortisol, which alters brain chemistry, which then affects memory. This chain shows which type of causality?", a:"Domino causality", d:["Linear causality","Cyclical causality","Reverse causality"], why:"In domino causality each effect becomes the next cause, like a line of falling dominoes."},
{id:"co20", t:"concepts", lv:1, q:"Which technique uses several methods, data sources or researchers to strengthen measurement?", a:"Triangulation", d:["Operationalisation","Counterbalancing","Random sampling"], why:"Triangulation checks one finding from several angles, so no single flawed measure decides the result."},
{id:"co21", t:"concepts", lv:3, q:"Sofia writes: 'Bandura's study is biased because it only looks at learning from a sociocultural angle.' What is the best correction?", a:"That is a perspective, not a bias", d:["Correct: one-approach studies are biased","It should say causality instead of bias","It should say the study was unethical"], why:"Taking one approach is a deliberate lens. Bias means an unintended systematic distortion, such as observer bias."},
{id:"co22", t:"concepts", lv:3, q:"Essay title: 'Discuss responsibility with regard to operant conditioning.' Which point is most relevant?", a:"Whether plans respect agency and avoid harm", d:["Whether Skinner box data were operationalised","Whether a true experiment was possible","Whether the Law of Effect is linear causality"], why:"Responsibility is about ethics and use: does a conditioning plan respect people and avoid harm?"},
{id:"co23", t:"concepts", lv:3, q:"Emil notes that Bransford and Johnson's participants rated their own comprehension on a 1 to 7 scale. Which concept is his point about?", a:"Measurement", d:["Responsibility","Change","Perspective"], why:"Self-ratings are subjective, so how comprehension was measured is open to question."},
{id:"co24", t:"concepts", lv:3, q:"Aisha points out that Sana et al. tested students at one Canadian university, a WEIRD sample. Which concept does this critique fit best?", a:"Bias", d:["Causality","Responsibility","Change"], why:"WEIRD sampling is a form of sampling and cultural bias that limits who the findings apply to."},
{id:"co25", t:"concepts", lv:3, q:"Glanzer and Cunitz manipulated the delay before recall under controlled conditions. In a causality essay, the best phrasing is...", a:"The manipulated delay supports a causal claim", d:["Causality was high because it was an experiment","The study proved that STM exists","Causality was low because it was a lab study"], why:"Explain what supports or limits a causal claim instead of labelling causality as simply high or low."},
{id:"co26", t:"concepts", lv:2, tf:1, q:"In a perspective essay, accurate points about ethics and generalisability still earn credit.", a:false, why:"Those points belong to other concepts. A perspective essay must weigh lenses, so they earn no credit there."},
{id:"co27", t:"concepts", lv:3, q:"Signe writes about Lord, Ross and Lepper using deception and needing to debrief participants. Which concept is she using?", a:"Responsibility", d:["Measurement","Causality","Perspective"], why:"Deception and debriefing are research ethics, which fall under responsibility."},
{id:"co28", t:"concepts", lv:3, q:"Mads compares a behaviourist and a cognitive explanation of why a student revises for rewards. Which concept is he developing?", a:"Perspective", d:["Bias","Causality","Measurement"], why:"Setting two explanations side by side and weighing them is a perspective argument."},

/* ---------- Classical conditioning ---------- */
{id:"cc01", t:"classical", lv:1, q:"In classical conditioning, learning happens through...", a:"Association between two stimuli", d:["Consequences that follow a behaviour","Watching a model being rewarded","Rehearsal of information in STM"], why:"A neutral stimulus comes to predict a stimulus that already triggers a reflex."},
{id:"cc02", t:"classical", lv:1, q:"In Pavlov's procedure, what was the unconditioned stimulus?", a:"Food", d:["The metronome","Salivation","The lab assistant"], why:"Food triggers salivation without any learning, so it is the unconditioned stimulus (UCS)."},
{id:"cc03", t:"classical", lv:1, q:"A dog salivating to food, before any learning has taken place, is the...", a:"Unconditioned response", d:["Conditioned response","Neutral stimulus","Conditioned stimulus"], why:"An unlearned reflex to the UCS is the unconditioned response (UCR)."},
{id:"cc04", t:"classical", lv:2, q:"After many pairings, the metronome alone made the dogs salivate. The metronome is now the...", a:"Conditioned stimulus", d:["Unconditioned stimulus","Neutral stimulus","Unconditioned response"], why:"The once-neutral stimulus has become a conditioned stimulus (CS) that triggers the response by itself."},
{id:"cc05", t:"classical", lv:1, tf:1, q:"Pavlov's original stimulus was a metronome, although examiners accept 'bell'.", a:true, why:"The dogs were conditioned to a metronome. Saying 'bell' does not lose marks, but know the detail."},
{id:"cc06", t:"classical", lv:1, q:"What is extinction in classical conditioning?", a:"The CR fades when the CS appears without the UCS", d:["The UCR slowly fades when the UCS is repeated often","The NS becomes a CS after a single pairing","The CR grows stronger with every pairing"], why:"Without the UCS, the CS stops predicting anything, so the conditioned response gradually dies away."},
{id:"cc07", t:"classical", lv:1, q:"What first led Pavlov to study conditioning?", a:"Dogs salivated on seeing the assistants who fed them", d:["Dogs refused food after hearing loud noises in the lab","Dogs learned to press levers for food","Dogs copied other dogs that were being fed"], why:"Pavlov was studying digestion and noticed the dogs had learned to expect food from the assistants."},
{id:"cc08", t:"classical", lv:2, q:"Which statement describes classical rather than operant conditioning?", a:"Two stimuli become linked automatically", d:["A behaviour changes because of what follows it","A rat presses a lever and gets a pellet","A fine follows littering and littering falls"], why:"Classical conditioning links stimuli. Operant conditioning links a behaviour to its consequence."},
{id:"cc09", t:"classical", lv:2, q:"A quick test to tell classical from operant conditioning is to ask...", a:"Does one stimulus predict another?", d:["Is the learner an animal or a human?","Was the reward given by a person?","Did the behaviour feel pleasant?"], why:"Stimulus predicts stimulus: classical. Consequence changes behaviour: operant."},
{id:"cc10", t:"classical", lv:2, q:"In aversion therapy for alcoholism, what plays the role of the UCS?", a:"A drug that causes nausea", d:["The alcohol itself","The feeling of nausea","The therapist's praise"], why:"The emetic drug causes nausea without learning. Alcohol is the neutral stimulus paired with it."},
{id:"cc11", t:"classical", lv:2, q:"In aversion therapy, alcohol is paired with a nausea-causing drug. After therapy, alcohol is the...", a:"Conditioned stimulus", d:["Unconditioned stimulus","Unconditioned response","Neutral stimulus"], why:"Alcohol now triggers nausea on its own, so it has become a conditioned stimulus."},
{id:"cc12", t:"classical", lv:2, tf:1, q:"In classical conditioning, the learner must perform a behaviour before any learning can happen.", a:false, why:"Classical conditioning works on reflexes. The learner simply experiences the pairing of stimuli."},
{id:"cc13", t:"classical", lv:3, q:"Garcia's rats avoided saccharin for over a month after one pairing with radiation sickness. What does this show?", a:"Taste aversion can form after one pairing", d:["Extinction happens after a single trial","Operant punishment reduces drinking","Rats imitate each other's food choices"], why:"Some associations, like taste and illness, are learned extremely quickly and last a long time."},
{id:"cc14", t:"classical", lv:1, q:"Thompson's rabbit eye-blink research found which brain area essential for the conditioned response?", a:"Cerebellum", d:["Hippocampus","Amygdala","Prefrontal cortex"], why:"Thompson linked the conditioned eye-blink to the cerebellum (the interpositus nucleus)."},
{id:"cc15", t:"classical", lv:1, tf:1, q:"Before conditioning, the neutral stimulus already produces the response being studied.", a:false, why:"A neutral stimulus produces no relevant response until it has been paired with the UCS."},
{id:"cc16", t:"classical", lv:2, q:"Pavlov assumed that learning in dogs tells us about learning in humans. Which concept does this assumption raise?", a:"Perspective", d:["Responsibility","Measurement","Change"], why:"The behaviourist lens treats animal learning as a model for humans, a reductionist perspective to weigh."},
{id:"cc17", t:"classical", lv:2, q:"Watson and Rayner's 'Little Albert' study is most often discussed under which concept?", a:"Responsibility", d:["Measurement","Causality","Perspective"], why:"Deliberately conditioning a strong fear in an infant raises serious ethical concerns."},
{id:"cc18", t:"classical", lv:3, q:"Maja's son dislikes reading. She plays his favourite music whenever he opens a book. In this plan, the music is the...", a:"Unconditioned stimulus", d:["Conditioned stimulus","Neutral stimulus","Conditioned response"], why:"The music already produces a good feeling without learning. Reading is the neutral stimulus paired with it."},
{id:"cc19", t:"classical", lv:3, q:"After weeks of music during reading, Oliver feels happy when he opens a book, even in silence. That happy feeling is the...", a:"Conditioned response", d:["Unconditioned response","Conditioned stimulus","Unconditioned stimulus"], why:"The good feeling is now triggered by the book alone, so it is a learned, conditioned response."},
{id:"cc20", t:"classical", lv:3, q:"Kenji ate sushi the night he fell ill with flu. Now the smell of sushi makes him queasy. The sushi smell is the...", a:"Conditioned stimulus", d:["Unconditioned stimulus","Unconditioned response","Neutral stimulus"], why:"The illness (UCS) caused nausea. Sushi, paired with it, now triggers nausea by itself."},
{id:"cc21", t:"classical", lv:3, q:"A dog salivates to a metronome. The metronome is then sounded many times with no food. What should happen?", a:"Salivation to the metronome gradually fades", d:["Salivation increases as the sound is familiar","The dog starts salivating to all sounds","Food no longer causes any salivation"], why:"This is extinction: the CS no longer predicts the UCS, so the CR weakens."},
{id:"cc22", t:"classical", lv:3, q:"Which plan uses classical conditioning to make revision feel pleasant for Freja?", a:"Pair revision with a treat she already enjoys", d:["Reward her after each finished hour","Let her watch a friend praised for revising","Take her phone away when she stops"], why:"Classical conditioning pairs the neutral activity with a stimulus that already gives a good feeling. The others are operant or SLT."},

/* ---------- Operant conditioning ---------- */
{id:"op01", t:"operant", lv:1, q:"Thorndike's Law of Effect says a behaviour followed by a satisfying consequence is...", a:"More likely to be repeated", d:["Less likely to be repeated","Linked to a neutral stimulus","Only repeated if it is observed"], why:"Pleasant consequences strengthen a behaviour; unpleasant ones weaken it. Skinner built on this."},
{id:"op02", t:"operant", lv:1, q:"In operant conditioning, 'positive' means...", a:"Something is added after the behaviour", d:["The consequence feels pleasant","The behaviour is morally good","The behaviour becomes more likely"], why:"Positive and negative describe adding or removing, not good or bad."},
{id:"op03", t:"operant", lv:1, q:"A reinforcer is defined by...", a:"Whether the behaviour becomes more likely", d:["How pleasant or enjoyable it feels to the learner","Who gives it, such as a teacher","Whether it was meant as a reward"], why:"Only the effect on future behaviour counts. If the behaviour does not increase, it was not a reinforcer."},
{id:"op04", t:"operant", lv:1, tf:1, q:"Negative reinforcement is another name for punishment.", a:false, why:"Negative reinforcement removes something unpleasant, so the behaviour increases. Punishment makes behaviour less likely."},
{id:"op05", t:"operant", lv:1, q:"Reinforcing successive approximations towards a target behaviour is called...", a:"Shaping", d:["Modelling","Extinction","Vicarious reinforcement"], why:"Shaping rewards closer and closer steps, and the criterion moves as the learner improves."},
{id:"op06", t:"operant", lv:1, q:"In the ABC of behaviour, what does A stand for?", a:"Antecedent", d:["Attention","Association","Aversive"], why:"Antecedent (the cue), Behaviour, Consequence: the consequence changes the future behaviour."},
{id:"op07", t:"operant", lv:1, q:"Thorndike demonstrated the Law of Effect using...", a:"Cats escaping from a puzzle box", d:["Pigeons pecking in a Skinner box","Dogs salivating to a metronome","Rats swimming in a water maze"], why:"The cats escaped faster over trials because escaping led to food."},
{id:"op08", t:"operant", lv:1, q:"In Skinner's superstition study, the pigeons received food...", a:"At regular intervals, whatever they did", d:["Only after pecking a key","Only after turning in a circle","After an unpredictable number of pecks"], why:"Food did not depend on behaviour, yet most pigeons repeated whatever they happened to be doing."},
{id:"op09", t:"operant", lv:2, q:"The seatbelt buzzer stops when you buckle up, and buckling up increases. This is...", a:"Negative reinforcement", d:["Positive punishment","Negative punishment","Positive reinforcement"], why:"An unpleasant sound is removed (negative) and the behaviour increases (reinforcement)."},
{id:"op10", t:"operant", lv:2, q:"A driver gets a fine for speeding and speeds less afterwards. This is...", a:"Positive punishment", d:["Negative reinforcement","Negative punishment","Positive reinforcement"], why:"Something unpleasant is added (positive) and the behaviour decreases (punishment)."},
{id:"op11", t:"operant", lv:3, q:"Lukas loses his gaming time whenever he skips homework, and he skips homework less often. This is...", a:"Negative punishment", d:["Negative reinforcement","Positive punishment","Positive reinforcement"], why:"Something pleasant is taken away (negative) and the behaviour decreases (punishment)."},
{id:"op12", t:"operant", lv:3, q:"Nadia takes a painkiller, her headache goes away, and she reaches for painkillers more often. This is...", a:"Negative reinforcement", d:["Positive reinforcement","Negative punishment","Positive punishment"], why:"The pain is removed (negative) and the behaviour becomes more likely (reinforcement)."},
{id:"op13", t:"operant", lv:2, q:"A teacher gives specific praise after strong answers, and strong answers increase. This is...", a:"Positive reinforcement", d:["Negative reinforcement","Positive punishment","Negative punishment"], why:"Praise is added and the behaviour increases, so it is positive reinforcement."},
{id:"op14", t:"operant", lv:2, q:"A loyalty card gives you a free coffee after every 10 you buy. Which schedule is this?", a:"Fixed ratio", d:["Variable ratio","Fixed interval","Variable interval"], why:"The reward depends on a set number of responses, so it is a fixed ratio schedule."},
{id:"op15", t:"operant", lv:2, q:"A slot machine pays out after an unpredictable number of plays. Which schedule is this?", a:"Variable ratio", d:["Fixed ratio","Fixed interval","Variable interval"], why:"The reward depends on the number of responses, and that number keeps changing."},
{id:"op16", t:"operant", lv:2, q:"Checking your phone for messages that arrive at unpredictable times is most like which schedule?", a:"Variable interval", d:["Fixed interval","Variable ratio","Fixed ratio"], why:"The reward depends on time passing, not on how often you check, and the time varies."},
{id:"op17", t:"operant", lv:2, q:"The first lever press after 30 seconds earns a pellet. Which schedule is this?", a:"Fixed interval", d:["Fixed ratio","Variable interval","Variable ratio"], why:"The rule depends on a set amount of time, then the first response is rewarded."},
{id:"op18", t:"operant", lv:1, tf:1, q:"Variable ratio schedules produce fast, persistent responding and are linked to gambling.", a:true, why:"Because the next response might always pay off, responding stays high and is hard to extinguish."},
{id:"op19", t:"operant", lv:2, tf:1, q:"Detention always counts as punishment, because the teacher intends it to punish.", a:false, why:"Do not classify by intention. It is punishment only if the behaviour becomes less likely."},
{id:"op20", t:"operant", lv:2, q:"Skinner explained his pigeons' odd, repeated movements as...", a:"Accidental reinforcement of chance actions", d:["Imitation of other pigeons in the box","Classical conditioning to the food hopper","Punishment of all their other movements"], why:"Food arrived by chance during a movement, so that movement was strengthened as if it had caused the food."},
{id:"op21", t:"operant", lv:2, q:"Staddon and Simmelhag challenged Skinner by arguing the pigeons' repeated actions were...", a:"Time-linked, species-typical behaviour", d:["Learned by watching the researcher","Caused by fear of the Skinner box","Evidence of conscious planning"], why:"They offered an alternative to 'accidental reinforcement', a useful perspective point."},
{id:"op22", t:"operant", lv:2, q:"A teacher asks a question, a student answers, and the teacher praises the answer. The praise is the...", a:"Consequence", d:["Antecedent","Behaviour","Schedule"], why:"A is the question (cue), B is the answer, C is the praise that follows it."},
{id:"op23", t:"operant", lv:3, q:"Ahmed is late to class every day. His teacher gives him a homework pass after every five on-time arrivals. Which schedule is she using?", a:"Fixed ratio", d:["Variable ratio","Fixed interval","Variable interval"], why:"A set number of responses (five on-time arrivals) earns the reward."},
{id:"op24", t:"operant", lv:3, q:"Chris chats and disrupts lessons. Which strategy is negative punishment?", a:"Move his seat away from his friends", d:["Praise him when he works quietly","Give him extra homework when he chats","Stop nagging him once he starts working"], why:"Time with friends, something pleasant, is removed so chatting decreases."},
{id:"op25", t:"operant", lv:3, q:"Signe lets herself watch one episode of a series only after each workout, and her workouts increase. This is...", a:"Positive reinforcement", d:["Negative reinforcement","Positive punishment","Negative punishment"], why:"A pleasant reward is added after the behaviour, and the behaviour increases."},
{id:"op26", t:"operant", lv:3, q:"A coach rewards Amara first for putting her face in the water, then for floating, then for swimming a stroke. This is...", a:"Shaping", d:["Modelling","Variable ratio","Negative reinforcement"], why:"Each reward is for a closer approximation to the target behaviour."},
{id:"op27", t:"operant", lv:2, q:"In a Section B answer on changing behaviour with operant conditioning, what does the examiner want?", a:"One strategy, correct terms, why it works", d:["All four quadrants, each briefly defined","A list of strengths and limitations of OC","A detailed account of the Skinner box"], why:"Pick one strategy, apply it to the scenario with correct terms, and explain why it would work."},
{id:"op28", t:"operant", lv:3, q:"Why do many psychologists prefer reinforcement to punishment for changing classroom behaviour?", a:"Punishment can bring emotional side effects", d:["Punishment never reduces a behaviour","Reinforcement needs no consequence at all","Reinforcement cannot be put on a schedule"], why:"Punishment can breed fear and resentment, while reinforcement builds the wanted behaviour."},
{id:"op29", t:"operant", lv:3, q:"People save money and exercise for rewards months away. Why is this a problem for a simple behaviourist account?", a:"Expectations shape behaviour, not just consequences", d:["It shows that humans cannot be conditioned at all","It proves punishment beats reward","It shows learning happens only by observation"], why:"Delayed rewards suggest thinking and expectation matter, which pure stimulus-response accounts leave out."},
{id:"op30", t:"operant", lv:3, tf:1, q:"Because Skinner's findings come from rats and pigeons, they apply to humans without any need for caution.", a:false, why:"Generalising from animals needs care: human behaviour also involves thoughts, expectations and culture."},

/* ---------- Social learning theory ---------- */
{id:"sl01", t:"slt", lv:1, q:"Social learning theory says we can learn a new behaviour by...", a:"Observing and imitating models", d:["Being directly reinforced every time","Pairing a neutral stimulus with a reflex","Repeating information in short-term memory"], why:"Bandura showed learning can happen without direct experience, just by watching others."},
{id:"sl02", t:"slt", lv:1, q:"Seeing a model rewarded, which makes you more likely to imitate them, is called...", a:"Vicarious reinforcement", d:["Negative reinforcement","Identification","Shaping"], why:"The reward is experienced second-hand, through the model, yet it still raises imitation."},
{id:"sl03", t:"slt", lv:1, q:"Which list gives Bandura's four mediating processes?", a:"Attention, retention, reproduction, motivation", d:["Attention, rehearsal, retrieval, motivation","Attention, retention, reinforcement, modelling","Attention, retention, self-efficacy, motivation"], why:"You must notice it, remember it, be able to do it and want to do it."},
{id:"sl04", t:"slt", lv:1, q:"Which mediating process depends on being physically and mentally able to perform the behaviour?", a:"Reproduction", d:["Retention","Attention","Motivation"], why:"Reproduction means you can actually carry the behaviour out, which needs self-efficacy."},
{id:"sl05", t:"slt", lv:1, q:"Belief in your own ability to carry out a behaviour is called...", a:"Self-efficacy", d:["Identification","Vicarious reinforcement","Retention"], why:"Low self-efficacy can block reproduction even when the behaviour was noticed and remembered."},
{id:"sl06", t:"slt", lv:1, q:"How many children took part in Bandura, Ross and Ross (1961)?", a:"72", d:["36","24","150"], why:"72 children took part: 36 boys and 36 girls."},
{id:"sl07", t:"slt", lv:1, q:"The children in Bandura, Ross and Ross (1961) were aged about...", a:"3 to nearly 6 years", d:["7 to nearly 11 years","6 to 9 years","1 to 2 years"], why:"They were nursery-age children, from about 3 to almost 6 years old."},
{id:"sl08", t:"slt", lv:1, q:"How long did the children watch the adult model in Bandura, Ross and Ross (1961)?", a:"About 10 minutes", d:["About 20 minutes","About 1 minute","About 1 hour"], why:"Modelling lasted about 10 minutes. The later test phase lasted about 20 minutes."},
{id:"sl09", t:"slt", lv:1, tf:1, q:"In Bandura's test phase, observers behind a one-way mirror coded behaviour every 5 seconds.", a:true, why:"Time sampling every 5 seconds over 20 minutes gave 240 response units per child."},
{id:"sl10", t:"slt", lv:2, q:"Why were children shown attractive toys and then told they could not play with them?", a:"To mildly arouse aggression before the test", d:["To reward them for watching the model","To check that they recognised the toys","To reduce demand characteristics"], why:"Mild frustration made aggression more likely, so any imitation could show in the test room."},
{id:"sl11", t:"slt", lv:3, q:"Bandura matched children across groups on how aggressive they already were. Why was this a sensible design choice?", a:"So groups began with similar aggression", d:["So every child saw both kinds of model","So raters did not know the conditions","So results would apply to all children"], why:"Matching controls a key participant variable, so differences are more likely due to the model."},
{id:"sl12", t:"slt", lv:1, q:"Inter-rater reliability for the aggression ratings in Bandura, Ross and Ross (1961) was...", a:"r = 0.89", d:["r = 0.29","r = 0.51","r = 0.98"], why:"A correlation of 0.89 between raters shows the aggression ratings were consistent."},
{id:"sl13", t:"slt", lv:2, q:"Which gender finding came from Bandura, Ross and Ross (1961)?", a:"Boys were more aggressive overall than girls", d:["Girls were more aggressive overall than boys","Only children with a same-sex model imitated","Girls copied male verbal aggression most"], why:"Boys were more aggressive overall and copied the male model more. Girls copied verbal aggression more from the female model."},
{id:"sl14", t:"slt", lv:2, tf:1, q:"Bandura's 1961 study showed that aggression is learned only by observation and is never innate.", a:false, why:"It showed aggression can be learned by observation. It did not test whether aggression is also innate."},
{id:"sl15", t:"slt", lv:3, q:"Children called the female model's aggression 'unladylike' but praised the male model. This suggests imitation was shaped by...", a:"Gender norms the children already held", d:["The length of the modelling session","The number of toys in the test room","The one-way mirror in the test room"], why:"The children's existing gender expectations affected which model they judged worth copying."},
{id:"sl16", t:"slt", lv:2, q:"Bandura, Ross and Ross (1963) extended the 1961 study by showing that...", a:"Filmed and cartoon aggression was copied too", d:["Same-sex models had no influence at all","Aggression disappeared after about 20 minutes","Punished models were copied the most"], why:"Aggression seen on film or as a cartoon was imitated too, compared with a no-film control."},
{id:"sl17", t:"slt", lv:2, q:"Gallese et al. (1996) found neurons in macaques that fired both when the monkey reached for food and when it...", a:"Watched a person reach for food", d:["Was rewarded with extra food","Heard a tone that was paired with food","Was alone in a new cage"], why:"These mirror neurons respond to doing and watching, a possible biological basis for imitation."},
{id:"sl18", t:"slt", lv:2, tf:1, q:"A child can only imitate a model who is the same age and gender as them.", a:false, why:"Similarity helps identification and imitation, but it is not required."},
{id:"sl19", t:"slt", lv:2, q:"In Coates et al. (2019), children who saw YouTubers with unhealthy snacks...", a:"Ate more food overall than the control group", d:["Ate no differently from the control group","Ate more fruit than the healthy-post group","Refused the snacks offered afterwards"], why:"They ate about 26% more than controls, mainly unhealthy snacks: models influenced eating."},
{id:"sl20", t:"slt", lv:2, tf:1, q:"In Coates et al. (2019), posts showing healthy food raised healthy eating compared with the control group.", a:false, why:"Healthy-food posts had no effect compared with the control. Only unhealthy-food posts changed intake."},
{id:"sl21", t:"slt", lv:2, q:"The Food Dudes programme (Lowe et al., 2004) used cartoon peer models plus rewards to...", a:"Raise children's fruit and vegetable intake", d:["Reduce aggression in the playground","Improve children's reading scores","Cut the time children spent on screens"], why:"Intake rose, lasted at a 4-month follow-up, and rose most in the children who ate least."},
{id:"sl22", t:"slt", lv:2, q:"Lowe et al. (2004) compared whole schools instead of randomly allocating children. This makes the study...", a:"Quasi-experimental", d:["A true laboratory experiment","A case study","A correlational survey"], why:"Without random allocation of individuals, groups may differ in other ways, limiting causal claims."},
{id:"sl23", t:"slt", lv:3, q:"Lucas watches his older brother get praised for tidying up. Later Lucas tidies his own room. Which SLT idea explains this?", a:"Vicarious reinforcement", d:["Negative reinforcement","Shaping","Accommodation"], why:"Lucas was not rewarded himself. Seeing his brother rewarded raised his motivation to imitate."},
{id:"sl24", t:"slt", lv:3, q:"Priya watches a tennis star's serve many times and remembers it well, but still cannot serve like her. Which process is the barrier?", a:"Reproduction", d:["Attention","Retention","Motivation"], why:"She noticed and remembered the serve but lacks the physical ability to reproduce it."},
{id:"sl25", t:"slt", lv:3, q:"A school wants more students to recycle. Which plan is based on social learning theory?", a:"Show admired students being praised for recycling", d:["Fine any student who puts cans in the general waste","Play a pleasant jingle each time a bin opens","Give a sticker to every student who recycles"], why:"An attractive model plus visible reward uses attention and vicarious reinforcement. The others are OC or CC."},
{id:"sl26", t:"slt", lv:3, q:"Jonas copies a local footballer his own age more than a famous older star. Which factor best explains this?", a:"Identification with the model", d:["Retention of the behaviour","Reproduction of the skill","Vicarious punishment"], why:"We imitate models we see as similar to ourselves more readily."},
{id:"sl27", t:"slt", lv:3, q:"Which is a valid criticism of Bandura's Bobo doll study?", a:"Hitting a toy doll may be play, not aggression", d:["It had no control group to compare results with","It used only adults as participants","Its observers could not see the children"], why:"Construct validity is doubtful: a toy built to be hit may not measure real aggression."},
{id:"sl28", t:"slt", lv:3, tf:1, q:"A weakness of SLT is that it leans towards nurture and struggles to explain individual differences on its own.", a:true, why:"Two children watching the same model may act differently; SLT alone cannot fully explain why."},

/* ---------- Schema theory ---------- */
{id:"sc01", t:"schema", lv:1, q:"A schema is best defined as...", a:"A mental representation built from experience", d:["A memory store with a small, limited capacity","A reflex triggered by a stimulus","A reward that makes a behaviour more likely"], why:"Schemas organise knowledge, guide attention and recall, and help us predict what comes next."},
{id:"sc02", t:"schema", lv:1, q:"Fitting new information into an existing schema is called...", a:"Assimilation", d:["Accommodation","Disequilibrium","Rationalisation"], why:"In assimilation the schema stays the same and the new information slots into it."},
{id:"sc03", t:"schema", lv:1, q:"When a schema is modified, or a new one created, to fit new information, this is...", a:"Accommodation", d:["Assimilation","Levelling","Sharpening"], why:"Accommodation changes the schema itself because the new information does not fit."},
{id:"sc04", t:"schema", lv:1, q:"A schema for a typical sequence of events, such as eating in a restaurant, is called a...", a:"Script", d:["Model","Heuristic","Chunk"], why:"Scripts are event schemas. They are learned in a culture, so they differ between cultures."},
{id:"sc05", t:"schema", lv:1, q:"Who were the participants in Bartlett's War of the Ghosts study?", a:"British participants", d:["Native American participants","American schoolchildren","Chinese university students"], why:"British participants recalled a Native American legend that clashed with their cultural schemas."},
{id:"sc06", t:"schema", lv:1, q:"In Bartlett's repeated reproduction method, he asked...", a:"One person to recall the story many times", d:["Each person to retell the story to the next","People to recognise the story from a list","People to rate how clear the story was"], why:"Repeated reproduction uses one person over time. Serial reproduction passes the story along a chain."},
{id:"sc07", t:"schema", lv:1, tf:1, q:"Schema theory can be used as your cognitive model of memory in Paper 1.", a:false, why:"Schema theory is a theory, not a cognitive model. Use the MSM or the WMM for a model question."},
{id:"sc08", t:"schema", lv:1, q:"In Bransford and Johnson (1972), the vague passage was really about...", a:"Washing clothes", d:["Baking bread","Planning a holiday","Fixing a bicycle"], why:"Without the topic, the passage about washing clothes was very hard to understand or recall."},
{id:"sc09", t:"schema", lv:1, q:"Bransford and Johnson scored recall against how many idea units?", a:"18", d:["7","52","72"], why:"Two independent judges scored recall against 18 idea units. 52 was the number of participants."},
{id:"sc10", t:"schema", lv:2, q:"A child calls a cow 'doggie', then learns that it is a different animal called a cow. Learning 'cow' shows...", a:"Accommodation", d:["Assimilation","Levelling","Rationalisation"], why:"The child's animal schema is changed, and a new category is created, to fit the new information."},
{id:"sc11", t:"schema", lv:2, q:"In Bartlett's study, 'canoe' became 'boat' and 'hunting seals' became 'fishing'. These changes show...", a:"Recall shifting to fit the reader's culture", d:["Details being recalled exactly as heard","The story growing longer with each recall","Random errors unrelated to schemas"], why:"Unfamiliar details were reshaped to fit British schemas, so memory is reconstructive."},
{id:"sc12", t:"schema", lv:2, q:"Dropping details that seem unimportant, so the story gets shorter, is called...", a:"Levelling", d:["Sharpening","Rationalisation","Assimilation"], why:"Levelling shortens the story. Bartlett's versions shrank to around 180 words after several reproductions."},
{id:"sc13", t:"schema", lv:2, q:"Changing a story so that it 'makes sense' within your own cultural expectations is called...", a:"Rationalisation", d:["Levelling","Sharpening","Accommodation"], why:"Rationalisation makes a strange story fit the reader's culture so it seems logical."},
{id:"sc14", t:"schema", lv:2, q:"What did Bartlett find when he compared repeated and serial reproduction?", a:"Both produced the same kinds of distortion", d:["Serial reproduction kept the story intact","Repeated reproduction made stories longer","Only serial reproduction caused distortion"], why:"Both methods showed the same kinds of change (shortening, familiarising, rationalising), which points to schemas rather than the method."},
{id:"sc15", t:"schema", lv:3, q:"Bartlett's recall intervals were irregular and he scored recall himself. What does this mainly weaken?", a:"Reliability, and it risks bias", d:["Ecological validity of the story","Informed consent of participants","Random allocation to conditions"], why:"An unstandardised procedure is hard to replicate, and scoring his own data opens the door to bias."},
{id:"sc16", t:"schema", lv:2, q:"Which group in Bransford and Johnson recalled the most idea units?", a:"Topic given before the passage", d:["Topic given after the passage","No topic given at all","All three groups recalled equally"], why:"Only knowing the topic before listening improved comprehension and recall."},
{id:"sc17", t:"schema", lv:2, tf:1, q:"In Bransford and Johnson, hearing the topic after the passage improved recall compared with no topic.", a:false, why:"Topic After did no better than No Topic. The schema has to be active when the passage is encoded."},
{id:"sc18", t:"schema", lv:2, q:"Bransford and Johnson concluded that prior knowledge helps memory when it is...", a:"Activated at encoding", d:["Activated only at retrieval","Rehearsed in short-term memory","Stored as a cultural script"], why:"Having the right schema is not enough; it must be switched on while the information is taken in."},
{id:"sc19", t:"schema", lv:2, q:"How was comprehension measured in Bransford and Johnson (1972)?", a:"Participants rated it on a 1 to 7 scale", d:["Judges counted errors in a summary","Reaction times to questions on the text","A multiple-choice test on the passage"], why:"Comprehension was self-rated, while recall was scored separately against idea units."},
{id:"sc20", t:"schema", lv:2, q:"In Anderson and Pichert, participants recalled new details after switching from a burglar to a homebuyer view. Schemas therefore affect...", a:"Retrieval as well as encoding", d:["Encoding, but not retrieval","Attention, but not recall","Sensory memory, but not LTM"], why:"The new perspective unlocked details already stored, so schemas guide retrieval too."},
{id:"sc21", t:"schema", lv:2, q:"In Brewer and Treyens (1981), which items did many students falsely recognise as having been in the office?", a:"Expected items, such as books", d:["Odd items, such as a skull","Items they had touched themselves","Items named by the experimenter"], why:"The office schema filled in books that were not there, while the unexpected skull was often missed."},
{id:"sc22", t:"schema", lv:2, q:"In Loftus and Palmer (1974), more people who heard the verb 'smashed' later reported...", a:"Broken glass that was not in the film", d:["No accident having happened at all","Fewer details about the cars","A different colour for the cars"], why:"About 32% in the 'smashed' group reported broken glass, against 12% of controls: memory is reconstructed."},
{id:"sc23", t:"schema", lv:3, q:"Cohen (1993) criticised schema theory mainly because the idea of a 'schema'...", a:"Is too vague to observe or measure", d:["Was never tested in experiments","Applies only to young children","Explains only memory for faces"], why:"If a schema cannot be measured, it is hard to test, which weakens construct validity."},
{id:"sc24", t:"schema", lv:2, tf:1, q:"Information that fits an existing schema is usually processed faster and with less effort than information that does not.", a:true, why:"Schema-congruent information is processed quickly, like System 1. Incongruent information takes more effort."},
{id:"sc25", t:"schema", lv:3, q:"Tomás describes a friend's birthday party and mentions a cake, though there was none. Which schema idea best explains this?", a:"Recall fills gaps with expected details", d:["The cake was displaced from his STM","He assimilated a brand new schema","He levelled the emotional details"], why:"His party schema supplied a typical detail: memory is reconstructive, not a recording."},
{id:"sc26", t:"schema", lv:3, q:"Kofi moves from a school that valued solo work to one built on group work. He avoids group tasks. Schema theory explains this because...", a:"His school schema expects solo work", d:["He was punished for group work before","He has never watched a model do group work","His phonological loop is overloaded"], why:"His existing schema of how school works guides his behaviour until it is accommodated."},
{id:"sc27", t:"schema", lv:3, q:"During a fire in a UK store restaurant, some diners reportedly stayed to pay their bill instead of fleeing. What best explains this?", a:"They followed a restaurant script", d:["They accommodated a new schema","They levelled out the danger cues","They were vicariously reinforced"], why:"The familiar restaurant script (eat, then pay) guided behaviour even in an emergency."},
{id:"sc28", t:"schema", lv:3, q:"Which is a fair criticism of explaining recall errors with schema theory?", a:"It is circular: schemas inferred from errors", d:["It has no experimental support at all","It cannot explain any kind of memory distortion","It has only been tested on animals"], why:"Saying 'they misremembered because of a schema' when the schema is known only from the error explains little."},
{id:"sc29", t:"schema", lv:3, tf:1, q:"Schema theory can explain memory distortion, which the MSM and WMM do not explain.", a:true, why:"The two memory models describe storage and processing but not why memories get reshaped."},
{id:"sc30", t:"schema", lv:3, q:"Hanna hears an ambiguous passage and is told its topic only afterwards. Based on Bransford and Johnson, her recall should be...", a:"No better than with no topic at all", d:["Much better than with no topic","Better than hearing the topic first","Perfect, once the topic is known"], why:"The schema was not active during encoding, so the late topic did not help."},

/* ---------- Multi-store model ---------- */
{id:"ms01", t:"msm", lv:1, q:"Who proposed the multi-store model of memory, and when?", a:"Atkinson and Shiffrin, 1968", d:["Baddeley and Hitch, 1974","Craik and Lockhart, 1972","Glanzer and Cunitz, 1966"], why:"Atkinson and Shiffrin (1968) described memory as sensory memory, STM and LTM in sequence."},
{id:"ms02", t:"msm", lv:1, q:"In the MSM, what moves information from sensory memory into STM?", a:"Attention", d:["Rehearsal","Retrieval","Displacement"], why:"Only what we attend to passes on; the rest fades from sensory memory."},
{id:"ms03", t:"msm", lv:1, q:"According to Miller (1956), the capacity of STM is about...", a:"7 ± 2 items", d:["3 ± 1 items","15 to 30 items","Unlimited"], why:"Miller's 'magical number seven' is a rough estimate, not a fixed biological limit."},
{id:"ms04", t:"msm", lv:1, q:"Cowan found that when people do not know how long a list will be, STM holds only about...", a:"3 to 5 items", d:["7 to 9 items","10 to 12 items","1 to 2 items"], why:"When strategies like rehearsal are harder to use, STM capacity looks smaller than Miller's 7 ± 2."},
{id:"ms05", t:"msm", lv:1, q:"Iconic memory holds a visual trace for roughly...", a:"0.2 to 0.5 seconds", d:["2 to 4 seconds","15 to 30 seconds","About 1 minute"], why:"Iconic memory is rich but fades within a fraction of a second."},
{id:"ms06", t:"msm", lv:1, q:"Echoic memory, the sensory store for sound, lasts roughly...", a:"2 to 4 seconds", d:["0.2 to 0.5 seconds","15 to 30 seconds","Several minutes"], why:"Echoic traces last a little longer than iconic ones, a few seconds."},
{id:"ms07", t:"msm", lv:1, q:"Without rehearsal, how long does information typically last in STM?", a:"About 15 to 30 seconds", d:["Under half a second","About 2 to 4 seconds","Several hours"], why:"STM is limited in duration as well as capacity; without rehearsal, information decays or is displaced."},
{id:"ms08", t:"msm", lv:1, q:"Repeating information over and over to keep it in STM is called...", a:"Maintenance rehearsal", d:["Elaborative rehearsal","Chunking","Retrieval"], why:"Maintenance rehearsal is simple repetition. Elaborative rehearsal links information to meaning."},
{id:"ms09", t:"msm", lv:1, tf:1, q:"In the MSM, new input can push older items out of a full STM. This is called displacement.", a:true, why:"Because STM capacity is limited, new items can knock out old ones before they are rehearsed."},
{id:"ms10", t:"msm", lv:2, q:"Linking new information to what you already know, which is more effective than repetition, is...", a:"Elaborative rehearsal", d:["Maintenance rehearsal","Displacement","Sensory registration"], why:"Elaborative rehearsal gives information meaning, which makes it more likely to last in LTM."},
{id:"ms11", t:"msm", lv:2, q:"In Sperling's partial report task, a tone played after the display told participants...", a:"Which row of letters to report", d:["How many letters had appeared","When to start rehearsing the grid","Whether letters or digits were shown"], why:"Because any cued row could be reported, the whole display must briefly have been available."},
{id:"ms12", t:"msm", lv:2, q:"Sperling's partial report findings suggest sensory memory is...", a:"High capacity but very short-lived", d:["Low capacity and short-lived","Low capacity but lasting for minutes","High capacity and long-lasting"], why:"Nearly any row could be reported if cued at once, but the advantage vanished as the cue was delayed."},
{id:"ms13", t:"msm", lv:2, q:"The MSM explains the primacy effect, better recall of the first items in a list, by...", a:"Early items being rehearsed into LTM", d:["Early items still being in STM","Early items being displaced","Early items staying in sensory memory"], why:"The first items get the most rehearsal, so they are transferred to LTM."},
{id:"ms14", t:"msm", lv:2, q:"According to the MSM, the recency effect happens because the last items in a list...", a:"Are still held in STM at recall", d:["Have been rehearsed into LTM","Are processed more deeply","Stay in echoic memory for minutes"], why:"The last few items have not yet decayed or been displaced from STM when recall starts."},
{id:"ms15", t:"msm", lv:1, q:"Who were the participants in Glanzer and Cunitz (1966)?", a:"46 enlisted army men", d:["72 nursery children","34 psychology students","52 university students"], why:"46 army men were tested individually in a repeated measures design."},
{id:"ms16", t:"msm", lv:2, q:"In Glanzer and Cunitz (1966), a 30-second counting task before recall...", a:"Removed the recency effect", d:["Removed the primacy effect","Removed both effects","Improved recall of the middle items"], why:"Counting blocked rehearsal of the last words, so they were lost from STM. Primacy was unaffected."},
{id:"ms17", t:"msm", lv:2, tf:1, q:"Glanzer and Cunitz found that a delay before recall reduced primacy as well as recency.", a:false, why:"Only recency was affected: sharply reduced at 10 seconds and gone at 30. Early words were already in LTM."},
{id:"ms18", t:"msm", lv:2, q:"Why does the Glanzer and Cunitz result support the MSM?", a:"It suggests STM and LTM are separate", d:["It shows STM has several components","It shows depth of processing matters","It shows memory is reconstructive"], why:"A delay affected only the end of the list, so the two ends seem to rely on different stores."},
{id:"ms19", t:"msm", lv:2, tf:1, q:"Chunking can turn several symbols into one meaningful unit, so 7 ± 2 is not a simple count of characters.", a:true, why:"A phone number grouped into chunks takes fewer slots than the same digits held one by one."},
{id:"ms20", t:"msm", lv:1, q:"In what year, and at what age, did HM have the brain surgery that caused his amnesia?", a:"1953, aged 27", d:["1966, aged 40","1953, aged 7","1926, aged 27"], why:"In 1953, at 27, tissue including most of both hippocampi was removed to treat his epilepsy."},
{id:"ms21", t:"msm", lv:2, q:"After his surgery, HM could not form new long-term memories of facts and events. This is...", a:"Anterograde amnesia", d:["Retrograde amnesia","Displacement","Procedural memory loss"], why:"Anterograde amnesia means new memories cannot be stored. Retrograde amnesia affects memories from before."},
{id:"ms22", t:"msm", lv:2, q:"HM kept the number 584 in mind for 15 minutes by constant rehearsal. What does this show?", a:"His short-term memory was intact", d:["His long-term memory was intact","His procedural memory was damaged","He could form new semantic memories"], why:"He could hold and rehearse information, but lost it once distracted: STM worked, transfer to LTM did not."},
{id:"ms23", t:"msm", lv:3, q:"HM improved at mirror drawing without remembering he had ever done it. Why does this challenge the MSM?", a:"LTM seems to have more than one store", d:["STM seems to have several parts","Sensory memory can last for years","HM's short-term memory was damaged"], why:"Procedural memory survived while new episodic memory did not, so LTM is not one single store."},
{id:"ms24", t:"msm", lv:2, tf:1, q:"HM's case supports the MSM claim that STM and LTM are separate.", a:true, why:"His STM worked while he could not form new LTM, so the two can be damaged separately."},
{id:"ms25", t:"msm", lv:3, q:"Ellie hears a 6-item shopping list, then her phone rings. Later she recalls only the first three items. Why were the last items lost?", a:"The call displaced them from STM", d:["They never reached sensory memory","They were in LTM but not retrieved","They were processed too deeply"], why:"The call blocked rehearsal and displaced the last items, while the first items had reached LTM."},
{id:"ms26", t:"msm", lv:3, q:"Mads writes about the 'central executive' while describing the MSM. What is wrong?", a:"He is mixing WMM terms into the MSM", d:["He should call it the phonological loop","He should place it in sensory memory","Nothing: the MSM has a central executive"], why:"The central executive belongs to the WMM. Mixing the two models' vocabulary is a common exam error."},
{id:"ms27", t:"msm", lv:3, q:"Which is a limitation of the MSM?", a:"It treats STM and LTM as single stores", d:["It has no experimental support at all","It cannot explain the primacy effect","It was tested only on animals"], why:"Evidence such as HM and the WMM suggests memory has more parts and more interaction than the MSM shows."},
{id:"ms28", t:"msm", lv:2, q:"Logie (1999) argued that STM is better seen as...", a:"A workstation that interacts with LTM", d:["A gateway items must pass to reach LTM","A store with unlimited capacity","A sensory buffer for sounds only"], why:"This challenges the MSM's picture of STM as a one-way gateway into LTM."},
{id:"ms29", t:"msm", lv:3, q:"Glanzer and Cunitz used lists of random, unconnected words. Which evaluation point follows?", a:"Low ecological validity: lists are artificial", d:["No control: nothing was manipulated","Low reliability: it cannot be replicated","High population validity: all were soldiers"], why:"Word lists are artificial, so the findings may not reflect memory in everyday life."},
{id:"ms30", t:"msm", lv:3, q:"You remember a shocking event after seeing it once. Why is this hard for the MSM to explain?", a:"It says rehearsal is needed to reach LTM", d:["It says LTM has a small capacity","It says sensory memory lasts for years","It says emotion always improves STM"], why:"The MSM leaves out emotion and learning with little rehearsal, a common criticism."},

/* ---------- Working memory model ---------- */
{id:"wm01", t:"wmm", lv:1, q:"Who proposed the working memory model, and when?", a:"Baddeley and Hitch, 1974", d:["Atkinson and Shiffrin, 1968","Craik and Lockhart, 1972","Landry and Bartling, 2011"], why:"Baddeley and Hitch (1974) argued that STM is a set of parts working together."},
{id:"wm02", t:"wmm", lv:1, q:"Which WMM component directs attention and sends information to the right subsystem?", a:"Central executive", d:["Phonological loop","Visuospatial sketchpad","Episodic buffer"], why:"The central executive focuses, divides and switches attention. It has limited capacity."},
{id:"wm03", t:"wmm", lv:1, q:"The 'inner voice' that rehearses words is the...", a:"Articulatory control process", d:["Phonological store","Visuospatial sketchpad","Episodic buffer"], why:"The articulatory control process rehearses words subvocally, refreshing the phonological store."},
{id:"wm04", t:"wmm", lv:1, q:"The 'inner ear' that holds sounds for about 2 seconds unless rehearsed is the...", a:"Phonological store", d:["Articulatory control process","Central executive","Visuospatial sketchpad"], why:"The phonological store holds speech sounds briefly; the inner voice keeps them alive."},
{id:"wm05", t:"wmm", lv:1, q:"Which component holds what things look like and where they are?", a:"Visuospatial sketchpad", d:["Phonological loop","Episodic buffer","Central executive"], why:"The sketchpad, the 'inner eye', handles shapes, locations, routes and movement."},
{id:"wm06", t:"wmm", lv:1, q:"Which component did Baddeley add later to combine sounds, images and LTM into one episode?", a:"Episodic buffer", d:["Phonological loop","Central executive","Visuospatial sketchpad"], why:"The episodic buffer integrates information from the subsystems and LTM. It has limited capacity too."},
{id:"wm07", t:"wmm", lv:1, tf:1, q:"The central executive is a permanent store for information.", a:false, why:"The central executive controls attention. It does not store information itself."},
{id:"wm08", t:"wmm", lv:1, q:"In Landry and Bartling (2011), what did the suppression group say aloud?", a:"'1, 2', at two numbers per second", d:["'A, B, C', once per second","The alphabet, quietly","Their own name, slowly"], why:"Repeating '1, 2' kept the inner voice busy, so the letters could not be rehearsed."},
{id:"wm09", t:"wmm", lv:1, q:"What were the mean recall scores in Landry and Bartling (2011)?", a:"76% control, 45% suppression", d:["45% control, 76% suppression","88% control, 25% suppression","76% control, 70% suppression"], why:"Suppression cut recall sharply (p ≤ 0.01), supporting a separate verbal subsystem."},
{id:"wm10", t:"wmm", lv:1, q:"How many participants did Landry and Bartling test, and in which design?", a:"34, independent samples (17 per group)", d:["34, repeated measures (all did both)","46, repeated measures (all did both)","72, matched pairs (36 per group)"], why:"34 psychology undergraduates were split into a control and a suppression group of 17 each."},
{id:"wm11", t:"wmm", lv:2, q:"Why did Landry and Bartling use letters such as F, K, L, M, R, X and Q?", a:"They sound different and are hard to chunk", d:["They look alike, so they test the sketchpad","They form common words when grouped","They rhyme, so they test the phonological store"], why:"Dissimilar-sounding letters with no vowels avoid confusion by sound and chunking into words."},
{id:"wm12", t:"wmm", lv:2, q:"Why did saying '1, 2' reduce recall in Landry and Bartling?", a:"It blocked rehearsal by the articulatory process", d:["It overloaded the visuospatial sketchpad","It pushed the letters into long-term memory","It shut down the episodic buffer"], why:"With the inner voice busy, the letters faded from the phonological store."},
{id:"wm13", t:"wmm", lv:2, q:"Dual-task logic: if two tasks can be done together with little loss, they probably...", a:"Use different components", d:["Use the same component","Both rely on long-term memory","Need no attention at all"], why:"Tasks that clash compete for the same component; tasks that coexist use different ones."},
{id:"wm14", t:"wmm", lv:2, tf:1, q:"In the WMM, two verbal tasks interfere with each other more than a verbal task and a visual task do.", a:true, why:"Two verbal tasks compete for the phonological loop, while a visual task uses the sketchpad."},
{id:"wm15", t:"wmm", lv:2, q:"Patient KF recalled letters poorly when read aloud but better when he saw them written. This supports...", a:"Separate verbal and visual STM stores", d:["A single, unitary short-term store","A split between STM and LTM only","The idea that his LTM was damaged"], why:"One short-term component was damaged while another worked, as the WMM predicts."},
{id:"wm16", t:"wmm", lv:2, q:"Why is KF especially useful evidence for the WMM rather than the MSM?", a:"One STM component failed while another worked", d:["His LTM failed while his STM was fine","He had the same amnesia as HM","He could no longer recall meaningful sounds"], why:"The MSM already separated STM and LTM. KF shows STM itself has separate parts."},
{id:"wm17", t:"wmm", lv:1, tf:1, q:"In Landry and Bartling (2011), each list had 7 letters and was shown for 5 seconds.", a:true, why:"After a 5-second wait, participants wrote the letters in order. There were 10 lists."},
{id:"wm18", t:"wmm", lv:2, q:"A key limitation of the WMM is that the central executive...", a:"Is vague and cannot be measured alone", d:["Has no link at all to long-term memory","Was removed when the buffer was added","Is a store with unlimited capacity"], why:"Every task that uses the central executive also uses a subsystem, so its capacity is never isolated."},
{id:"wm19", t:"wmm", lv:2, tf:1, q:"There is no biological evidence for the WMM.", a:false, why:"KF, and brain scans that show different areas for verbal and visual tasks, give biological support."},
{id:"wm20", t:"wmm", lv:2, q:"The key change the WMM made to the MSM was that...", a:"STM has several parts, not one store", d:["LTM is several stores, not one","Sensory memory lasts far longer than thought","STM has an unlimited capacity"], why:"Baddeley and Hitch replaced the single STM box with a set of interacting components."},
{id:"wm21", t:"wmm", lv:3, q:"A footballer hears three quick spoken instructions from his coach mid-game and forgets one. Which component was most overloaded?", a:"Phonological loop", d:["Visuospatial sketchpad","Episodic buffer","Sensory register"], why:"Spoken instructions are held in the phonological loop, which has a small capacity."},
{id:"wm22", t:"wmm", lv:3, q:"Aisha drives on a quiet, familiar road while chatting and copes fairly well. The WMM explains this because...", a:"They use different subsystems", d:["Both tasks use the phonological loop","The central executive has no limit","Driving is held in the episodic buffer"], why:"Tasks using different subsystems clash less, though switching still costs something."},
{id:"wm23", t:"wmm", lv:3, q:"Sam tries to hold a phone number in mind while a friend reads names aloud. Why does he struggle?", a:"Both tasks need the phonological loop", d:["The tasks use different subsystems","His visuospatial sketchpad is full","His episodic buffer has shut down"], why:"Two verbal tasks need the same component, so they interfere with each other."},
{id:"wm24", t:"wmm", lv:3, q:"Freja listens to a podcast while talking with a friend and follows neither well. Which WMM idea explains this?", a:"Two verbal tasks compete for the same loop", d:["Different subsystems work in parallel","The sketchpad is holding the podcast","Her LTM capacity has been exceeded"], why:"Both tasks are verbal, so they overload the phonological loop."},
{id:"wm25", t:"wmm", lv:3, q:"Nikolaj memorises a route while tapping a pattern on the desk. Why is this harder than memorising it while chanting?", a:"Tapping and the route both use the sketchpad", d:["Chanting uses the sketchpad instead","Tapping blocks the phonological loop","The route is held in the episodic buffer"], why:"Spatial tapping competes with the route in the visuospatial sketchpad; chanting uses the loop."},
{id:"wm26", t:"wmm", lv:3, q:"Which is a fair evaluation point about Landry and Bartling (2011)?", a:"Letter lists are artificial: low ecological validity", d:["It had no control group to compare with","Its repeated measures design caused order effects","It tested 150 people from many countries"], why:"Recalling letter lists in a lab is far from everyday memory. The small student sample is another limit."},
{id:"wm27", t:"wmm", lv:2, q:"Which everyday pairing does the WMM predict will cause the least interference?", a:"Listening to music while drawing", d:["Listening to a podcast while chatting","Reciting a poem while counting aloud","Holding a phone number while hearing names"], why:"Sound and drawing use different subsystems, so they can run side by side."},
{id:"wm28", t:"wmm", lv:3, q:"Why is the WMM often seen as an improvement on the MSM's account of STM?", a:"It explains which tasks can be combined", d:["It fully explains long-term memory","It explains why memories get distorted","It shows STM has unlimited capacity"], why:"Splitting STM into components explains dual-task results that a single store cannot."},

/* ---------- Levels of processing ---------- */
{id:"lp01", t:"lop", lv:1, q:"Who proposed the levels of processing approach, and when?", a:"Craik and Lockhart, 1972", d:["Craik and Tulving, 1975","Baddeley and Hitch, 1974","Atkinson and Shiffrin, 1968"], why:"Craik and Lockhart (1972) proposed LOP. Craik and Tulving (1975) later tested it."},
{id:"lp02", t:"lop", lv:1, q:"According to LOP, how long a memory lasts depends on...", a:"How deeply it is processed at encoding", d:["Which store it is held in","How many times it is repeated","How long it stays in sensory memory"], why:"LOP asks what kind of processing happened, not where the memory is stored."},
{id:"lp03", t:"lop", lv:1, q:"Which level of processing focuses on meaning?", a:"Semantic", d:["Structural","Phonological","Visual"], why:"Semantic processing is the deepest level and gives the most durable memories."},
{id:"lp04", t:"lop", lv:1, q:"'Does the word rhyme with CAT?' requires which level of processing?", a:"Phonological", d:["Structural","Semantic","Elaborative"], why:"Rhyme judgements are about sound, which is phonological (shallow) processing."},
{id:"lp05", t:"lop", lv:2, q:"'Is the word in capital letters?' requires which level of processing?", a:"Structural", d:["Phonological","Semantic","Episodic"], why:"Judging appearance is structural processing, the shallowest level."},
{id:"lp06", t:"lop", lv:2, q:"'Is the word a type of fish?' requires which level of processing?", a:"Semantic", d:["Structural","Phonological","Procedural"], why:"Deciding category membership needs the word's meaning."},
{id:"lp07", t:"lop", lv:1, tf:1, q:"LOP proposes a fourth memory store for deeply processed information.", a:false, why:"LOP is not a store. It is an alternative explanation of memory based on depth of processing."},
{id:"lp08", t:"lop", lv:2, q:"In Craik and Tulving (1975), why was the memory test a surprise?", a:"To study incidental learning", d:["To test recall after a long delay","To make the test less stressful","To measure sensory memory"], why:"If people do not know a test is coming, recall reflects the processing task, not memorising effort."},
{id:"lp09", t:"lop", lv:2, q:"Craik and Tulving operationalised depth of processing by...", a:"Asking different questions about words", d:["Timing how long each word was studied","Counting how often words were repeated","Measuring brain activity during reading"], why:"Questions about case, rhyme or meaning forced structural, phonemic or semantic processing."},
{id:"lp10", t:"lop", lv:2, tf:1, q:"In Craik and Tulving (1975), words processed for meaning were recognised more often than words processed for appearance.", a:true, why:"Recognition rose with depth, supporting the idea that deeper processing makes memories more durable."},
{id:"lp11", t:"lop", lv:2, q:"How does LOP challenge the MSM?", a:"It says depth matters, not just repetition", d:["It shows STM has several components","It shows sensory memory is unlimited","It proves LTM is a single store for all memories"], why:"The MSM treats rehearsal as one general process; LOP shows the type of processing matters."},
{id:"lp12", t:"lop", lv:3, q:"A main limitation of LOP is that depth of processing...", a:"Cannot be measured apart from recall", d:["Has never been tested experimentally","Only applies to visual material","Explains only short-term memory"], why:"If deep means 'well remembered', and well remembered means 'deep', the argument is circular."},
{id:"lp13", t:"lop", lv:3, q:"In a class test of LOP, some 'shallow' participants secretly picture what each word means. Which problem does this show?", a:"Depth is hard to control or check", d:["The sample is too WEIRD to generalise","Participants may be harmed by the task","The IV was not manipulated at all"], why:"Researchers cannot see what processing actually happened, so the IV may leak between groups."},
{id:"lp14", t:"lop", lv:3, q:"Signe revises by copying key terms in neat capitals. Based on LOP, what would help her more?", a:"Explaining each term in her own words", d:["Copying each term out more times","Writing each term in a new colour","Reading the terms aloud faster"], why:"Working with meaning is deep, semantic processing. Copying and colouring stay shallow."},
{id:"lp15", t:"lop", lv:3, q:"Omar decides whether each word rhymes with 'tree'. What does LOP predict about his later recall of those words?", a:"Better than appearance, worse than meaning", d:["Better than meaning-based processing tasks","The same as for any other task","Worse than appearance-based tasks"], why:"Phonological processing sits between structural (shallowest) and semantic (deepest)."},
{id:"lp16", t:"lop", lv:3, q:"Which result would most challenge LOP?", a:"Rhymed words beating meaning words", d:["Meaning words recalled best of all","Capital-letter words recalled least well","Deep processing aiding recognition"], why:"LOP predicts semantic processing beats phonological. The reverse would contradict it."},
{id:"lp17", t:"lop", lv:2, tf:1, q:"LOP agrees with the MSM that simple repetition is the main route into LTM.", a:false, why:"LOP argues that meaningful, deep processing, not repetition, makes memories durable."},
{id:"lp18", t:"lop", lv:3, q:"Dimitri learns new vocabulary by linking each word to a vivid personal memory. In LOP terms this is...", a:"Deep, semantic processing", d:["Shallow, structural processing","Shallow, phonological processing","Maintenance rehearsal"], why:"Linking words to meaning and personal knowledge is deep processing, so recall should be better."},

/* ---------- Cognitive load theory ---------- */
{id:"cl01", t:"load", lv:1, q:"Cognitive load is best defined as...", a:"The total demand placed on working memory", d:["Using too much technology at once","The amount stored in long-term memory","The physical effort a task requires"], why:"Working memory is limited, so when demand exceeds capacity, learning and recall suffer."},
{id:"cl02", t:"load", lv:1, q:"The load that comes from how difficult the task itself is, is called...", a:"Intrinsic load", d:["Extraneous load","Germane load","Internal load"], why:"Intrinsic load depends on how many elements must be held and combined at once."},
{id:"cl03", t:"load", lv:1, q:"Load caused by distractions or poor presentation, unrelated to the task, is called...", a:"Extraneous load", d:["Intrinsic load","Germane load","Internal load"], why:"Extraneous load is the easiest type for teachers and students to remove."},
{id:"cl04", t:"load", lv:1, q:"The mental effort that goes into building reusable schemas is called...", a:"Germane load", d:["Intrinsic load","Extraneous load","Internal load"], why:"Germane load is useful effort: it builds schemas that make later learning easier."},
{id:"cl05", t:"load", lv:1, tf:1, q:"'Internal load' is one of the three types of cognitive load.", a:false, why:"The three types are intrinsic, extraneous and germane. 'Internal load' is a common mix-up."},
{id:"cl06", t:"load", lv:1, q:"Who described humans as 'cognitive misers'?", a:"Fiske and Taylor", d:["Baddeley and Hitch","Craik and Lockhart","Bransford and Johnson"], why:"We save mental effort wherever we can, because capacity is limited."},
{id:"cl07", t:"load", lv:2, q:"A revision sheet is crowded with clashing colours and pop-up adverts. This adds...", a:"Extraneous load", d:["Intrinsic load","Germane load","Internal load"], why:"The clutter has nothing to do with the content, but it still uses up working memory."},
{id:"cl08", t:"load", lv:2, tf:1, q:"Calculus has more intrinsic load than simple arithmetic.", a:true, why:"Calculus needs more elements held and combined at once, so the task itself is harder."},
{id:"cl09", t:"load", lv:2, q:"Worrying about a test while you are taking it adds which type of load?", a:"Extraneous load", d:["Intrinsic load","Germane load","Internal load"], why:"Worry is unrelated to the task, but it takes up working memory capacity."},
{id:"cl10", t:"load", lv:2, q:"After cracking one code, a second similar code feels much easier. Why?", a:"A schema now does some of the work", d:["Extraneous load has doubled","Intrinsic load has risen","Working memory capacity has grown"], why:"The effort on the first code was germane: it built a schema that now does some of the work."},
{id:"cl11", t:"load", lv:2, q:"Sana et al. (2013) mainly supports which idea?", a:"Distractions add load and harm learning", d:["Multitasking improves lecture learning","Note-taking removes intrinsic load","Screens are a source of germane load"], why:"Multitasking, and even seeing others' screens, lowered comprehension of a lecture."},
{id:"cl12", t:"load", lv:2, tf:1, q:"In Sana et al. (2013), students who did not multitask but could see others' laptops also scored lower.", a:true, why:"Just having multitasking laptops in view lowered comprehension: extraneous load from the environment."},
{id:"cl13", t:"load", lv:2, q:"In Mani et al. (2013), poorer participants scored lower on Raven's matrices when they had just thought about...", a:"A costly car repair", d:["A cheap car repair","Being paid for correct answers","Their next holiday"], why:"Worrying about a large bill used up mental capacity, but only for those short of money."},
{id:"cl14", t:"load", lv:2, q:"Mani et al.'s Indian sugarcane farmers scored higher on Raven's matrices...", a:"After harvest than before", d:["Before harvest than after","Only when paid per correct answer","Only in the lab version of the task"], why:"Before harvest, money worries took up capacity. The same farmers did better once they were paid."},
{id:"cl15", t:"load", lv:2, q:"Why is the farmer study in Mani et al. (2013) a natural experiment?", a:"The IV happened naturally, not by design", d:["Farmers were randomly allocated to groups","It took place in an outdoor setting","Researchers chose the harvest date"], why:"The researchers did not manipulate the IV; they tested the farmers when the harvest cycle allowed."},
{id:"cl16", t:"load", lv:3, q:"Which is the strongest measurement criticism of Mani et al. (2013)?", a:"Load was inferred, never measured directly", d:["The sample was a WEIRD student group","Raven's matrices only measure memory span","The farmers were tested only once"], why:"Load was assumed from income or season. Diet, sleep and practice also change after a harvest."},
{id:"cl17", t:"load", lv:3, tf:1, q:"Brain scans can measure cognitive load directly.", a:false, why:"Physiological measures show brain activity or arousal, which has to be interpreted as load."},
{id:"cl18", t:"load", lv:3, q:"Freja revises a new topic with a video playing and her phone buzzing with a group chat. Which change cuts extraneous load?", a:"Put the phone in another room", d:["Choose a harder topic first","Add a second video on the topic","Revise for four hours with no breaks"], why:"The chat has nothing to do with the topic, so removing it frees working memory for learning."},
{id:"cl19", t:"load", lv:3, q:"Emil finds a new maths topic very hard. His teacher breaks it into smaller steps. Which load is being managed?", a:"Intrinsic load", d:["Extraneous load","Germane load","Internal load"], why:"You cannot remove intrinsic load, but smaller steps mean fewer elements are held at once."},
{id:"cl20", t:"load", lv:3, q:"Why can 'just focus harder' be poor advice for an overloaded learner?", a:"The room or task design may cause the load", d:["Focusing harder raises working memory limits","Extraneous load can never be reduced","Germane load should always be zero"], why:"A system can work perfectly and still fail if the environment demands too much of it."},
{id:"cl21", t:"load", lv:3, q:"A top answer on Freja's revision shows how the types of load interact. Which link is best?", a:"Extraneous load leaves less room for germane", d:["High germane load creates extraneous load","Intrinsic load disappears with technology","Extraneous load builds useful schemas"], why:"Capacity is shared: effort wasted on distraction cannot go into building schemas."},
{id:"cl22", t:"load", lv:3, q:"Which is a problem with measuring cognitive load by self-report?", a:"People may misjudge their own effort", d:["It cannot be used with students","It measures only intrinsic load","It gives purely physiological data"], why:"Self-report can be biased, performance can drop for other reasons, and physiology shows arousal: none is perfect."},

/* ---------- Dual process theory ---------- */
{id:"dp01", t:"dpt", lv:1, q:"Which description fits System 1?", a:"Fast, automatic and low in effort", d:["Slow, effortful and analytic","Conscious and rule-based","Reliable but uncertain"], why:"System 1 runs on heuristics and gives quick gut answers that feel certain."},
{id:"dp02", t:"dpt", lv:1, q:"Which description fits System 2?", a:"Slow, conscious and effortful", d:["Fast, automatic and intuitive","Driven by heuristics and gut feeling","Automatic and prone to error"], why:"System 2 works through possibilities step by step and needs time, motivation and spare capacity."},
{id:"dp03", t:"dpt", lv:1, q:"The mental rules of thumb that System 1 relies on are called...", a:"Heuristics", d:["Algorithms","Mediators","Idea units"], why:"Heuristics are shortcuts: usually good enough, but they can cause systematic errors."},
{id:"dp04", t:"dpt", lv:1, q:"In the bat-and-ball problem, what is the common intuitive answer for the ball?", a:"10 cents", d:["5 cents","1 cent","50 cents"], why:"10 cents comes to mind instantly, but then the bat would cost 1.10 and the total 1.20."},
{id:"dp05", t:"dpt", lv:1, q:"In the bat-and-ball problem, what is the correct price of the ball?", a:"5 cents", d:["10 cents","1 cent","50 cents"], why:"A 5-cent ball plus a bat costing 1.00 more (1.05) gives the 1.10 total."},
{id:"dp06", t:"dpt", lv:1, tf:1, q:"A cognitive bias is systematic: most people make the same error in the same direction.", a:true, why:"That is what makes a bias different from random mistakes."},
{id:"dp07", t:"dpt", lv:2, q:"Working out 17 × 24 in your head mainly uses...", a:"System 2", d:["System 1","Neither system","Sensory memory"], why:"Mental multiplication needs slow, deliberate, step-by-step work."},
{id:"dp08", t:"dpt", lv:2, q:"Flinching when a ball flies towards your face is an example of...", a:"System 1", d:["System 2","Elaborative rehearsal","Deliberate reasoning"], why:"It is fast, automatic and needs no effort or conscious thought."},
{id:"dp09", t:"dpt", lv:2, q:"Comparing two phone contracts line by line mainly uses...", a:"System 2", d:["System 1","A heuristic","An automatic script"], why:"Careful comparison of options is slow, conscious and effortful."},
{id:"dp10", t:"dpt", lv:2, tf:1, q:"Completing 'salt and ...' without thinking is an example of System 1.", a:true, why:"The answer pops up automatically with no effort, which is typical of System 1."},
{id:"dp11", t:"dpt", lv:2, q:"When is System 1 most likely to take over from System 2?", a:"Under high cognitive load or time pressure", d:["When a person is rested and motivated","When the task is abstract logic","When a friend checks the answer"], why:"System 2 needs spare capacity and time. Without them, fast System 1 answers go unchecked."},
{id:"dp12", t:"dpt", lv:2, tf:1, q:"System 2 answers are usually more reliable but feel less certain than System 1 answers.", a:true, why:"System 1 gives a strong sense of certainty even when it is wrong."},
{id:"dp13", t:"dpt", lv:2, q:"Why do so many people answer 10 cents in the bat-and-ball problem?", a:"System 2 fails to check System 1's answer", d:["System 2 overcorrects the right answer","They lack basic arithmetic skills","The problem is too long for STM"], why:"The quick answer feels right, so effortful checking never starts. The opposite skill is cognitive reflection."},
{id:"dp14", t:"dpt", lv:2, q:"Few people solve Wason's abstract four-card task, but many solve a version about drinking ages. This suggests...", a:"Familiar context helps reasoning", d:["Abstract logic is easier than rules","System 1 always gives the right answer","Drinking is more memorable than cards"], why:"Griggs and Cox found far more correct answers when the same logic was set in a familiar context."},
{id:"dp15", t:"dpt", lv:2, q:"How does the cognitive miser idea fit dual process theory?", a:"We use System 1 to save effort", d:["We always use System 2 to avoid errors","System 2 needs no mental capacity","We store every decision in LTM"], why:"Slow reasoning is costly, so it is brought in only when it has to be."},
{id:"dp16", t:"dpt", lv:3, q:"Laila concentrates hard at every junction as a new driver. A year later she drives home without thinking. What has changed?", a:"Driving has moved from System 2 to System 1", d:["Driving has moved from System 1 to System 2","She now uses both systems equally","Driving is now a confirmation bias"], why:"With practice, an effortful skill becomes automatic."},
{id:"dp17", t:"dpt", lv:3, q:"Tobias answers a trick maths question quickly and wrongly just before the bell. Which explanation fits best?", a:"Time pressure let System 1 answer unchecked", d:["System 2 was too careful and slow","He followed a script from a past lesson","His schema was accommodated too fast"], why:"With little time, System 2 does not step in to check the intuitive answer."},
{id:"dp18", t:"dpt", lv:3, q:"Which habit would most help people avoid the bat-and-ball error?", a:"Slowing down and checking the answer", d:["Answering as fast as possible","Doing a second task at the same time","Reading the problem only once"], why:"Deliberate checking brings in System 2, which can catch the intuitive mistake."},
{id:"dp19", t:"dpt", lv:3, q:"A researcher wants to show that System 1 dominates under load. Which design fits best?", a:"Add a memory task and compare errors", d:["Ask people which system they prefer","Scan brains while people rest","Compare boys' and girls' answers"], why:"Adding a memory load (the IV) should increase intuitive errors if System 2 is starved of capacity."},
{id:"dp20", t:"dpt", lv:3, tf:1, q:"Dual process theory says System 1 is always wrong and should be avoided.", a:false, why:"System 1 handles most everyday tasks well. Errors arise when its answer goes unchecked."},

/* ---------- Cognitive biases ---------- */
{id:"bi01", t:"biases", lv:1, q:"Anchoring bias means we...", a:"Rely on the first number and adjust too little", d:["Seek evidence that fits our beliefs","Judge by how easily examples come to mind","Ignore how common something is"], why:"We adjust away from the first value, but not far enough, even if the anchor is random."},
{id:"bi02", t:"biases", lv:1, q:"Confirmation bias means we...", a:"Seek and favour evidence that fits our beliefs", d:["Rely on the first number we hear","Judge by how the options are worded","Judge by how easily examples come to mind"], why:"We seek, interpret and remember evidence in ways that support what we already believe."},
{id:"bi03", t:"biases", lv:1, q:"In Tversky and Kahneman (1974), which product did people estimate as larger in 5 seconds?", a:"8 × 7 × 6 × 5 × 4 × 3 × 2 × 1", d:["1 × 2 × 3 × 4 × 5 × 6 × 7 × 8","Both were estimated about the same","Both were estimated accurately"], why:"People anchor on the first few steps: large numbers first give a higher estimate."},
{id:"bi04", t:"biases", lv:1, q:"Wason's 2-4-6 task is used to demonstrate...", a:"Confirmation bias", d:["Anchoring bias","The framing effect","The availability heuristic"], why:"People test sequences that confirm their rule instead of ones that could disprove it."},
{id:"bi05", t:"biases", lv:1, q:"Confirmation bias works through selective exposure, selective interpretation and selective...", a:"Retention", d:["Reinforcement","Reproduction","Rehearsal"], why:"We also remember confirming evidence better than evidence against our view."},
{id:"bi06", t:"biases", lv:2, tf:1, q:"In anchoring, even a random number can pull people's estimates towards it.", a:true, why:"The anchor need not be relevant. Even dice rolls have shifted judges' sentences."},
{id:"bi07", t:"biases", lv:2, q:"Why do people give a lower estimate for 1 × 2 × ... × 8 than for 8 × 7 × ... × 1?", a:"They anchor on the first steps", d:["They look for evidence for a guess they like","They recall examples of big numbers","They see the task as a possible loss"], why:"Starting with small numbers sets a low anchor, and adjustment from it is not enough."},
{id:"bi08", t:"biases", lv:2, q:"Englich and colleagues found that legal professionals' sentences were influenced by...", a:"A random number, such as a dice roll", d:["The defendant's past record only","The weather on the day of the trial","The advice of a jury"], why:"An irrelevant number anchored their sentences, showing experts are not immune."},
{id:"bi09", t:"biases", lv:2, q:"Strack and Mussweiler asked for Gandhi's age at death after a high or low number. What happened?", a:"Estimates moved towards the number", d:["The number had no effect at all","Estimates moved away from the number","Only the low number was ignored"], why:"Even an absurd anchor shifted the estimates towards it."},
{id:"bi10", t:"biases", lv:2, q:"Lord, Ross and Lepper (1979) gave people for and against capital punishment mixed evidence. What happened?", a:"Both sides became more extreme", d:["Both sides moved towards the middle","Only the supporters changed their views","Neither side rated the studies differently"], why:"Each side rated the study that agreed with it as better, so attitudes polarised."},
{id:"bi11", t:"biases", lv:2, q:"Only reading news sites that agree with your views is an example of...", a:"Selective exposure", d:["Selective retention","Selective interpretation","Anchoring"], why:"Choosing what information you are exposed to is the first route of confirmation bias."},
{id:"bi12", t:"biases", lv:2, q:"Remembering only the times your horoscope was right is an example of...", a:"Selective retention", d:["Selective exposure","The framing effect","Anchoring"], why:"Confirming cases are remembered and disconfirming ones forgotten."},
{id:"bi13", t:"biases", lv:2, q:"The framing effect means people decide differently about the same information depending on...", a:"How it is presented", d:["Who presents it to them","How often they have seen it","How many options there are"], why:"The same facts framed as gains or losses, or survival or death, lead to different choices."},
{id:"bi14", t:"biases", lv:2, q:"People prefer meat labelled '75% lean' to the same meat labelled '25% fat'. This is...", a:"The framing effect", d:["Anchoring bias","The availability heuristic","Confirmation bias"], why:"The information is identical; only the wording changes the judgement."},
{id:"bi15", t:"biases", lv:2, q:"After seeing news of a plane crash, Alma judges flying as more dangerous than it is. This fits...", a:"The availability heuristic", d:["The framing effect","Anchoring bias","Confirmation bias"], why:"Vivid, recent examples come to mind easily, so they seem more common than they are."},
{id:"bi16", t:"biases", lv:2, tf:1, q:"The availability heuristic means judging how likely something is by how easily examples come to mind.", a:true, why:"Dramatic causes of death, for example, are overestimated because they are easy to recall."},
{id:"bi17", t:"biases", lv:3, q:"A jacket is marked 'was 2000 kr, now 999 kr'. Mathias thinks it is a bargain. Which bias is the shop using?", a:"Anchoring bias", d:["Confirmation bias","The framing effect","The availability heuristic"], why:"The 'was' price sets a high anchor, so the sale price seems cheap by comparison."},
{id:"bi18", t:"biases", lv:3, q:"Chen is sure one phone brand is the best and dismisses all bad reviews of it as fake. Which bias is this?", a:"Confirmation bias", d:["Anchoring bias","The framing effect","The availability heuristic"], why:"He explains away evidence that goes against his existing belief."},
{id:"bi19", t:"biases", lv:3, q:"In a Section A answer on anchoring bias, what is a common mistake?", a:"Not explaining why the bias happens", d:["Giving one example only","Using System 1 to explain the bias","Linking the example to the theory"], why:"Top answers describe the bias, give one example and explain why it happens (System 1, too little adjustment)."},
{id:"bi20", t:"biases", lv:3, q:"Sara's first salary offer is 30,000 kr, so she asks for 32,000 kr, although the job is worth much more. Which bias?", a:"Anchoring bias", d:["Confirmation bias","The framing effect","The availability heuristic"], why:"The first offer anchored her counter-offer, and she adjusted too little away from it."},
{id:"bi21", t:"biases", lv:3, q:"A scientist runs only tests that could prove her theory right, never ones that could prove it wrong. Which bias, and what fixes it?", a:"Confirmation bias; test to falsify", d:["Anchoring bias; use a larger sample","Framing effect; reword the questions","Availability; add more examples"], why:"Researchers are prone to confirmation bias too, which is why science values falsification."},
{id:"bi22", t:"biases", lv:3, q:"Why is Englich's research with legal professionals useful when evaluating anchoring?", a:"Experts are affected, not just students", d:["It shows anchoring vanishes in real courts","It proves judges are deliberately biased","It shows anchors only work with money"], why:"Much anchoring research uses students; experts showing the bias strengthens its real-world relevance."},
{id:"bi23", t:"biases", lv:3, tf:1, q:"When asked to explain anchoring bias, writing only about dual process theory can still earn full marks.", a:false, why:"Answering a different theory scores only 1 or 2 out of 4. Explain the bias itself, then link to System 1."},
{id:"bi24", t:"biases", lv:3, q:"In Wason's 2-4-6 task, most people test only sequences that fit their rule, such as 8-10-12. Why is this confirmation bias?", a:"They only seek confirming cases", d:["They anchor on the number 2","They forget the sequence too quickly","They frame the numbers as gains"], why:"Only a test that could fail their rule would reveal it is wrong."},

/* ---------- Cognitive models ---------- */
{id:"mo01", t:"models", lv:1, q:"Which is a reason psychologists use cognitive models?", a:"To simplify processes that cannot be seen", d:["To prove exactly how memories are stored","To replace the need for experiments","To predict one person's behaviour perfectly"], why:"Models make invisible processes concrete, testable and easy to communicate."},
{id:"mo02", t:"models", lv:1, tf:1, q:"If memory is your cognitive process, you need to know only one model of it, such as the MSM or the WMM.", a:true, why:"One model of one cognitive process is required. The old requirement to compare two models was dropped."},
{id:"mo03", t:"models", lv:1, q:"Breaking a process into parts helps researchers to...", a:"Test one component at a time", d:["Avoid collecting any data","Observe mental processes directly","Skip operationalising variables"], why:"Separate components let researchers make and test precise predictions."},
{id:"mo04", t:"models", lv:2, q:"Which is a limitation of cognitive models?", a:"Their constructs are hard to measure", d:["They cannot make any predictions","They are never tested empirically","They include too much about emotion"], why:"Stores and components are hypothetical, so they are inferred from behaviour, not seen."},
{id:"mo05", t:"models", lv:2, q:"Why does drawing the MSM alone not earn full marks?", a:"You must also describe how parts interact", d:["Examiners never accept diagrams in answers","Diagrams must show brain areas","The MSM has no parts to draw"], why:"A diagram shows structure but not the processes, like attention and rehearsal, that link the parts."},
{id:"mo06", t:"models", lv:2, q:"'All models are wrong, but some are useful' (George Box) means...", a:"Models simplify but can still guide research", d:["Drop a model once one study fails","Only biological models are useful","A useful model must be correct in every detail"], why:"No model captures everything, but a good one produces predictions worth testing."},
{id:"mo07", t:"models", lv:2, q:"Why must constructs like 'rehearsal' be operationalised when testing a model?", a:"So they can be measured in a study", d:["So the model can be drawn","So participants can give consent","So the model applies to all cultures"], why:"Without a measurable definition, a prediction from the model cannot be tested."},
{id:"mo08", t:"models", lv:2, tf:1, q:"A single study usually tests every part of a cognitive model at once.", a:false, why:"One study rarely tests a whole model. It usually tests one prediction about one component."},
{id:"mo09", t:"models", lv:3, q:"Researchers test a three-stage model of imagination with children. Data fit stages 1 and 3 but not stage 2. What is the best conclusion?", a:"Partly supported; stage 2 needs revising", d:["The whole model is proven correct","The whole model should now be rejected","Models cannot be tested on children"], why:"Empirical tests support or challenge parts of a model, which is how models get refined."},
{id:"mo10", t:"models", lv:3, q:"How does Landry and Bartling's study show the value of a cognitive model?", a:"The WMM made a testable prediction", d:["It proved the WMM is complete","It measured the central executive directly","It showed models need no data"], why:"The model predicted suppression would harm verbal recall; the study tested and supported that."},
{id:"mo11", t:"models", lv:3, q:"In a Section B answer on the value of cognitive models, which point is strongest?", a:"Models make predictions that studies test", d:["Models are useful because they are correct","Models let us see mental processes directly","Models remove the need to operationalise"], why:"The value of a model lies in guiding research that can support, challenge or refine it."},
{id:"mo12", t:"models", lv:2, q:"The MSM leaves out emotion and memory distortion. Which general limitation of models does this show?", a:"Models oversimplify processes", d:["Models are too hard to draw","Models can never be tested","Models only apply to animals"], why:"Simplifying is a strength and a weakness: important features can be left out."},
{id:"mo13", t:"models", lv:3, q:"Which is the best example of testing a cognitive model empirically?", a:"Blocking rehearsal to test recency", d:["Asking people if memory has stores","Drawing the MSM from memory","Describing HM's childhood"], why:"The MSM predicts recency depends on STM rehearsal. Glanzer and Cunitz tested exactly that."},
{id:"mo14", t:"models", lv:3, q:"Mikkel says the WMM is useless because the central executive cannot be measured. What is the best reply?", a:"A limit, but it still guides research", d:["The central executive is easy to scan","Models never need to be tested","The WMM has no central executive"], why:"A vague component is a weakness, but the rest of the model still makes testable predictions."},

/* ---------- Paper 1 exam technique ---------- */
{id:"ex01", t:"exam", lv:1, q:"How long is Paper 1?", a:"90 minutes", d:["2 hours","60 minutes","75 minutes"], why:"Suggested timing: about 20 minutes for A, 30 for B and 40 for C."},
{id:"ex02", t:"exam", lv:1, q:"What does Section A of Paper 1 contain?", a:"Two compulsory questions, 4 marks each", d:["Three compulsory questions, 9 marks each","Two compulsory questions, 6 marks each","A choice of 1 of 2 questions, 15 marks"], why:"Each A question asks you to describe or explain a content point with one example."},
{id:"ex03", t:"exam", lv:1, q:"What does Section B of Paper 1 contain?", a:"Two 6-mark questions on unseen scenarios", d:["Two 4-mark questions on named studies","One 15-mark essay from a choice of two","Three 9-mark short-answer questions"], why:"Section B asks you to apply theory to a short unseen scenario."},
{id:"ex04", t:"exam", lv:1, q:"In Section C of Paper 1, students...", a:"Choose 1 of 2 questions, worth 15 marks", d:["Answer both questions, 15 marks each","Choose 1 of 3 questions, 22 marks","Answer one compulsory 6-mark question"], why:"Section C is a concept-based extended response, and the two choices come from different contexts."},
{id:"ex05", t:"exam", lv:1, tf:1, q:"Paper 1 is the same for SL and HL students.", a:true, why:"Same paper, same rubrics. HL differs only in Paper 3."},
{id:"ex06", t:"exam", lv:1, q:"Which command terms are used in Section A?", a:"Describe or explain", d:["Discuss or evaluate","To what extent or examine","Compare and contrast"], why:"Describe asks what something is; explain asks why or how it works."},
{id:"ex07", t:"exam", lv:2, tf:1, q:"In Section A, if you give two examples, the examiner marks the better one.", a:false, why:"Only the first example is marked. Extra examples waste time."},
{id:"ex08", t:"exam", lv:2, q:"What is the difference between 'describe' and 'explain'?", a:"Describe says what; explain says why or how", d:["Describe needs a study; explain does not","Explain says what; describe says why","They mean the same in Paper 1"], why:"A description on an 'explain' question tends to earn only about half marks."},
{id:"ex09", t:"exam", lv:2, q:"In Section A, what can count as your one example?", a:"A study or an everyday example", d:["Only a named, published study","Only a personal experience","No example is needed for 4 marks"], why:"An everyday example is fine, but you must link it explicitly to the content point."},
{id:"ex10", t:"exam", lv:2, q:"What should a Section B answer NOT include?", a:"Evaluation of the theory", d:["A short explanation of the theory","Links to details in the scenario","Accurate terminology"], why:"Section B rewards explaining and applying. Evaluation earns nothing there."},
{id:"ex11", t:"exam", lv:2, q:"A Section B answer explains operant conditioning well but never mentions the scenario. Roughly how well can it score?", a:"About half marks at most", d:["Full marks, if the theory is accurate","Five out of six, losing one for style","Zero, as theory alone earns nothing"], why:"Without application the second strand is missing. Guidance suggests a cap of about 3 out of 6."},
{id:"ex12", t:"exam", lv:2, q:"Which topic can be asked ONLY in Section C?", a:"Strategies to improve memory", d:["Classical conditioning","Social learning theory","Cognitive load theory"], why:"Strategies, like improving memory, are Section C only. The others can appear in A or B."},
{id:"ex13", t:"exam", lv:1, q:"Each Section C question combines...", a:"A concept and an area of study", d:["Two studies from the same approach","A scenario with a named theory","A research method with one study"], why:"For example: 'Discuss perspective with regard to one model of one cognitive process.'"},
{id:"ex14", t:"exam", lv:1, tf:1, q:"Most Section C questions will use the command term 'discuss'.", a:true, why:"Discuss is most common, but evaluate, to what extent and examine are possible."},
{id:"ex15", t:"exam", lv:2, q:"How should a Section C conclusion be written?", a:"Follow from the argument and add nothing new", d:["Bring in a new study to finish strongly","Repeat the question word for word","List all six concepts briefly"], why:"A reasoned conclusion consistent with the argument is part of the top markband."},
{id:"ex16", t:"exam", lv:3, q:"Question: 'Explain classical conditioning with reference to one example.' Which plan fits best?", a:"Explain terms, then map them onto one example", d:["Describe Pavlov fully, then two more examples","Evaluate the strengths and weaknesses of CC","Compare classical with operant conditioning"], why:"Two strands: explain the content, then give one example and link each term to it."},
{id:"ex17", t:"exam", lv:3, q:"A Section C essay discusses bias at length but never describes an environmental effect on memory. What happens?", a:"It scores low: no area of study", d:["Full marks, as the concept is the focus","It is not marked at all","It loses one mark for length"], why:"The concept must be applied to the content. An essay like this was capped at about 9."},
{id:"ex18", t:"exam", lv:3, q:"In Section B, Aarav writes only: 'Praising Tom when he arrives on time is positive reinforcement.' What is his answer missing?", a:"An explanation of why it would work", d:["A named study with its sample size","An evaluation of the theory","A second, different theory"], why:"Labelling is not explaining. Say 'this happens because...' and link it to scenario details."},
{id:"ex19", t:"exam", lv:3, q:"In a Section C essay, where should the links between the concept and the content go?", a:"Throughout every paragraph", d:["All together in the conclusion","Only in the introduction","In a separate final section"], why:"Top essays keep the concept and content linked all the way through, not as an add-on."},
{id:"ex20", t:"exam", lv:3, q:"A Section C perspective essay on the MSM spends paragraphs on study methodology. Why does this lose marks?", a:"The focus should be weighing perspectives", d:["Methodology is banned in Paper 1","Studies are only allowed in Section A","Perspective essays need no content"], why:"Study details are not assessed in C. Keep the concept, here perspective, at the centre."},

/* ---------- Research methods ---------- */
{id:"me01", t:"methods", lv:1, q:"In an independent samples design...", a:"Each participant does only one condition", d:["Each participant does every condition","Participants are paired on key traits","One person is studied in depth"], why:"Different people in each condition means no order effects, but groups may differ."},
{id:"me02", t:"methods", lv:2, q:"Glanzer and Cunitz tested each participant in every delay condition. This design is...", a:"Repeated measures", d:["Independent samples","Matched pairs","A natural experiment"], why:"The same people did all conditions, which controls participant variables but risks boredom."},
{id:"me03", t:"methods", lv:2, q:"Bandura matched children on pre-rated aggression before putting them in groups. This reflects which design?", a:"Matched pairs", d:["Independent samples, unmatched","Repeated measures","Case study"], why:"Children were matched in threes on aggression ratings and split across conditions: groups start out alike, while each child is in one condition."},
{id:"me04", t:"methods", lv:1, q:"Inter-rater reliability checks...", a:"Whether observers score things alike", d:["Whether a test measures what it claims","Whether results apply to other groups","Whether participants guessed the aim"], why:"Bandura's raters correlated at r = 0.89, which shows consistent coding."},
{id:"me05", t:"methods", lv:1, q:"When participants guess the aim of a study and change their behaviour, this is called...", a:"Demand characteristics", d:["Inter-rater reliability","Order effects","Random allocation"], why:"Cues in a study can reveal the aim, so behaviour reflects the guess, not the IV."},
{id:"me06", t:"methods", lv:2, tf:1, q:"An advantage of an independent samples design is that there are no order effects.", a:true, why:"Nobody does both conditions, so practice or boredom cannot carry over."},
{id:"me07", t:"methods", lv:2, q:"Testing only students from one university mainly limits...", a:"Population validity", d:["Ecological validity","Inter-rater reliability","Internal validity"], why:"A narrow sample limits who the results generalise to. Ecological validity is about the setting."},
{id:"me08", t:"methods", lv:3, q:"Kasper says a lab study where people recalled letter lists tells us little about remembering a real conversation. Which term fits?", a:"Low ecological validity", d:["Low population validity","Low inter-rater reliability","Demand characteristics"], why:"Ecological validity asks whether a task and setting reflect real life."},
{id:"me09", t:"methods", lv:1, tf:1, q:"Studying one person in depth, like HM, is a case study, and its findings are hard to generalise.", a:true, why:"Rich data come from one person, so we cannot be sure every brain works the same way."},
{id:"me10", t:"methods", lv:2, q:"Researchers used IQ tests, interviews, observation and MRI to study HM. This is an example of...", a:"Method triangulation", d:["Random allocation","Counterbalancing","Matched pairs"], why:"Several methods pointing the same way make the findings more credible."},
{id:"me11", t:"methods", lv:2, q:"In Landry and Bartling, p ≤ 0.01 means...", a:"A 1% or lower probability of a chance result", d:["The hypothesis has now been proven to be true","1% of participants showed the effect","The results are 99% ecologically valid"], why:"The null hypothesis can be rejected, but significance never means proven."},
{id:"me12", t:"methods", lv:1, q:"WEIRD samples are Western, Educated, Industrialised, Rich and...", a:"Democratic", d:["Diverse","Developed","Disciplined"], why:"Much psychology samples WEIRD groups, which may not represent most of the world's people."},
{id:"me13", t:"methods", lv:3, q:"Random allocation in Sana et al. (2013) mainly strengthens...", a:"That multitasking caused the lower scores", d:["The ecological validity of the lecture","The population validity of the sample","The inter-rater reliability of scores"], why:"Random allocation spreads participant differences evenly, so the IV is the likelier cause."},
{id:"me14", t:"methods", lv:2, q:"Defining 'aggression' as the number of times a child hits Bobo in 20 minutes is an example of...", a:"Operationalisation", d:["Triangulation","Random allocation","Counterbalancing"], why:"Turning a construct into something countable makes it measurable in a study."},
{id:"me15", t:"methods", lv:3, q:"Aisha compares pupils' memory before and after their school closes for reasons she cannot control. This is a...", a:"Natural experiment", d:["True laboratory experiment","Case study","Matched pairs design"], why:"The IV changes naturally; the researcher does not manipulate it or allocate participants."},
{id:"me16", t:"methods", lv:3, q:"Two of Bandura's observers knew some of the children. What is the main risk?", a:"Observer bias in coding the behaviour", d:["Order effects between conditions","Low population validity","Participants dropping out"], why:"Observers who know a child may expect certain behaviour and rate it unevenly."}
];
